"use client";

import { useState, useEffect } from "react";
import ReactMarkdown from "react-markdown";
import { 
  ClipboardCheck, 
  Camera, 
  CalendarDays, 
  FileText, 
  Users, 
  Info,
  CheckCircle2,
  Wallet
} from "lucide-react";
import React from "react";

interface Section {
  title: string;
  items: string[];
}

interface StepResultProps {
  data: {
    intro?: string;
    sections: Section[];
    outro?: string;
  };
  localDeadlineStr?: string | null;
  onCoachClick?: () => void;
}

/**
 * Helper function to dynamically assign an icon based on the section title generated by AI.
 */
const getSectionIcon = (title: string, index: number) => {
  const lowerTitle = title.toLowerCase();
  if (lowerTitle.includes("admin") || lowerTitle.includes("priority") || lowerTitle.includes("action") || lowerTitle.includes("checklist")) return ClipboardCheck;
  if (lowerTitle.includes("record") || lowerTitle.includes("setup") || lowerTitle.includes("slate") || lowerTitle.includes("tape") || lowerTitle.includes("format")) return Camera;
  if (lowerTitle.includes("role") || lowerTitle.includes("character") || lowerTitle.includes("performance") || lowerTitle.includes("prep")) return FileText;
  if (lowerTitle.includes("schedule") || lowerTitle.includes("date") || lowerTitle.includes("time") || lowerTitle.includes("deadline")) return CalendarDays;
  if (lowerTitle.includes("people") || lowerTitle.includes("team") || lowerTitle.includes("contact") || lowerTitle.includes("creative")) return Users;
  if (lowerTitle.includes("fee") || lowerTitle.includes("finance") || lowerTitle.includes("contract") || lowerTitle.includes("buyout")) return Wallet;
  
  // Fallback icons if no keyword matches
  const fallbacks = [Info, CheckCircle2, FileText];
  return fallbacks[index % fallbacks.length];
};

export function StepResultBrief({ data, localDeadlineStr, onCoachClick }: StepResultProps) {
  const [activeSection, setActiveSection] = useState("section-0");

  useEffect(() => {
    if (!data?.sections || data.sections.length === 0) return;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setActiveSection(entry.target.id);
          }
        });
      },
      { rootMargin: "-20% 0px -60% 0px" }
    );

    const sectionElements = document.querySelectorAll('div[id^="section-"]');
    sectionElements.forEach((s) => observer.observe(s));

    return () => observer.disconnect();
  }, [data]);

  if (!data || !data.sections) return null;

  const renderMarkdown = (text: string) => (
    <div className="prose prose-slate max-w-none prose-p:m-0 prose-p:inline prose-strong:font-semibold prose-strong:text-gray-900">
      <ReactMarkdown>{text}</ReactMarkdown>
    </div>
  );

  const scrollToSection = (id: string) => {
    const element = document.getElementById(id);
    if (element) {
      element.scrollIntoView({ behavior: "smooth", block: "start" });
      setActiveSection(id);
    }
  };

  return (
    <div className="w-full grid grid-cols-1 lg:grid-cols-[1fr_280px] gap-10 items-start mt-8 pb-12 font-sans relative">
      
      {/* LEFT COLUMN: MAIN CONTENT */}
      <div className="space-y-6">
        
        {/* Intro Block */}
        {data.intro && (
          <div className="rounded-2xl bg-white shadow-sm p-6 sm:p-8 border border-gray-200/60 mb-6">
            <h4 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4">Audition Details</h4>
            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-6">
              {(() => {
                // Tolerant intro parser. The brief AI returns `intro` as a free-form string
                // (per BRIEF_ANALYSIS_PROMPT), so we accept several drift patterns:
                //   - Plain "Project: Foo"
                //   - Bolded "**Project:** Foo" or "**Project**: Foo"
                //   - Dash separator "Project - Foo" / "Project — Foo"
                //   - Trailing colon variants and surrounding whitespace
                // If the parser produces 0 fields, we fall back to rendering the whole intro.
                const LABELS = [
                  "CRITICAL WARNING",
                  "WARNING",
                  "Strict Deadline",
                  "Deadline",
                  "Project",
                  "Role",
                  "Type",
                ];
                // Strip markdown bold/italic so the splitter doesn't trip on `**Project:**`.
                const cleaned = data.intro.replace(/\*\*/g, "").replace(/__/g, "");
                // Build a regex that captures any label followed by `:` or ` -` or ` —`.
                const labelGroup = LABELS.map((l) => l.replace(/ /g, "\\s+")).join("|");
                const splitter = new RegExp(`(${labelGroup})\\s*[:\\-—]\\s*`, "gi");
                const parts = cleaned.split(splitter);

                if (parts.length <= 1) {
                  return (
                    <div className="col-span-full text-sm text-gray-700 leading-relaxed">
                      {data.intro}
                    </div>
                  );
                }

                // Capture any prose that came BEFORE the first label so it's not lost.
                const prelude = parts[0]?.trim();

                const items: Array<{ label: string; value: string }> = [];
                for (let i = 1; i < parts.length; i += 2) {
                  const rawLabel = (parts[i] || "").trim();
                  const rawValue = (parts[i + 1] || "").replace(/^[.\s]+|[.\s]+$/g, "").trim();
                  if (!rawLabel || !rawValue) continue;
                  items.push({ label: rawLabel, value: rawValue });
                }

                if (items.length === 0) {
                  return (
                    <div className="col-span-full text-sm text-gray-700 leading-relaxed">
                      {data.intro}
                    </div>
                  );
                }

                return (
                  <>
                    {prelude && (
                      <div className="col-span-full text-sm text-gray-600 italic leading-relaxed">
                        {prelude}
                      </div>
                    )}
                    {items.map((item, idx) => {
                      const isWarning = item.label.toUpperCase().includes("WARNING");
                      return (
                        <div
                          key={idx}
                          className={isWarning ? "col-span-full bg-[#FFF5F0] p-5 rounded-xl border border-[#FF7316]/20 mt-2" : "flex flex-col gap-1.5"}
                        >
                          <span className={`text-[10px] font-bold uppercase tracking-wider ${isWarning ? "text-[#FF7316]" : "text-gray-400"}`}>
                            {item.label}
                          </span>
                          <span className={`text-sm ${isWarning ? "text-gray-900 font-medium leading-relaxed" : "text-gray-900 font-semibold"}`}>
                            {item.value}
                          </span>
                        </div>
                      );
                    })}
                  </>
                );
              })()}
            </div>
          </div>
        )}

        {/*
          Local-deadline pill removed from this card on 2026-05 — the detail page and
          wizard result page now render it in the header so it sits above BOTH analysis
          cards (Sides + Brief). The `localDeadlineStr` prop is kept on this component
          so the wizard can still pass it for backward-compat callers, but no UI hangs
          off it here. Drop the prop on a future cleanup once all callers migrate.
        */}

        {/* Dynamic Sections Loop */}
        {data.sections.map((section, idx) => {
          const sectionId = `section-${idx}`;
          const SectionIcon = getSectionIcon(section.title, idx);
          
          // Clean title (removes "1. " or "Phase 1: " if AI added it)
          const cleanTitle = section.title.replace(/^(\d+\.|Phase \d+:)\s*/i, '');

          return (
            <div key={idx} id={sectionId} className="rounded-2xl bg-[#FCFAF7] shadow-sm p-6 sm:p-8 border border-gray-200/50 scroll-mt-8">
              <div className="flex items-center gap-3 mb-6 border-b border-gray-200/50 pb-4">
                <SectionIcon className="text-[#FF7316]" size={24} />
                <h3 className="text-xl font-bold text-gray-900">{cleanTitle}</h3>
              </div>
              
              <div className="space-y-4">
                {section.items.map((item, i) => {
                  // Smart Parser
                  const splitIndex = item.indexOf(':');
                  const isKeyValPair = splitIndex !== -1 && splitIndex < 60; 
                  
                  if (isKeyValPair) {
                    const header = item.substring(0, splitIndex).trim();
                    const description = item.substring(splitIndex + 1).trim();
                    
                    return (
                      <div key={i} className="flex flex-col gap-1.5 p-4 bg-white border border-gray-100 rounded-xl hover:border-[#FF7316]/30 transition-colors">
                          <div className="font-bold text-gray-900 text-[14px] uppercase tracking-wide">{renderMarkdown(header)}</div>
                          <div className="text-gray-600 text-[15px] leading-relaxed">{renderMarkdown(description)}</div>
                      </div>
                    );
                  }

                  return (
                    <div key={i} className="flex gap-3 items-start pl-2">
                      <span className="text-[#FF7316] mt-0.5 shrink-0 text-lg leading-none">•</span>
                      <div className="text-gray-700 text-[15px] leading-relaxed">
                        {renderMarkdown(item)}
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          );
        })}

        {/* Outro Block */}
        {data.outro && (
          <div className="rounded-2xl bg-transparent p-6 sm:p-8 text-gray-600 text-center">
            <div className="prose prose-slate max-w-none prose-p:italic prose-p:m-0 text-sm">
              <ReactMarkdown>{data.outro}</ReactMarkdown>
            </div>
          </div>
        )}

        {onCoachClick && (
          <div className="mt-2">
            <button
              onClick={onCoachClick}
              className="w-full rounded-full bg-[#E8721A] py-4 text-base font-semibold text-white transition-colors hover:bg-[#d66a18]"
            >
              Take this to my Coach →
            </button>
            <p className="mt-2 text-center text-sm text-[#6B6B6B]">
              Open a coaching session with this breakdown pre-loaded
            </p>
          </div>
        )}
      </div>

      {/* RIGHT COLUMN: DYNAMIC SIDEBAR NAVIGATION */}
      {data.sections.length > 0 && (
        <div className="hidden lg:block sticky top-10 rounded-2xl bg-[#FCFAF7] shadow-sm p-6 border border-gray-200/50">
          <h4 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-6">Workflow</h4>
          <nav>
            <ul className="space-y-2">
              {data.sections.map((section, idx) => {
                const sectionId = `section-${idx}`;
                const isActive = activeSection === sectionId;
                const Icon = getSectionIcon(section.title, idx);
                const cleanTitle = section.title.replace(/^(\d+\.|Phase \d+:)\s*/i, '');

                return (
                  <li key={sectionId}>
                    <button 
                      onClick={() => scrollToSection(sectionId)}
                      className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-colors border text-left ${
                        isActive 
                          ? "bg-[#FDECE2] text-[#FF7316] border-transparent" 
                          : "text-gray-600 hover:bg-gray-100 hover:text-gray-900 border-transparent hover:border-gray-200"
                      }`}
                    >
                      <Icon  size={18} className='shrink-0  text-[#FF7316] '/>
                      <span className="truncate">{cleanTitle}</span>
                    </button>
                  </li>
                );
              })}
            </ul>
          </nav>
        </div>
      )}
    </div>
  );
}